     1|/**
     2| * ModuleErrorBoundary — per-module crash isolation.
     3| *
     4| * Wraps individual screen sections (Reels, Members, Projects, Deals) so a
     5| * crash in one module shows a retry button for that section instead of
     6| * crashing the entire application.
     7| *
     8| * Error categories: AUTH_ERROR, NETWORK_ERROR, DATA_ERROR, RENDER_ERROR,
     9| * CONFIG_ERROR, UNKNOWN_ERROR
    10| */
    11|import React, { Component, type ReactNode } from 'react';
    12|import { View, Text, StyleSheet, TouchableOpacity, ActivityIndicator } from 'react-native';
    13|import { RefreshCw, AlertCircle } from 'lucide-react-native';
    14|
    15|type ErrorCategory =
    16|  | 'AUTH_ERROR'
    17|  | 'NETWORK_ERROR'
    18|  | 'DATA_ERROR'
    19|  | 'RENDER_ERROR'
    20|  | 'CONFIG_ERROR'
    21|  | 'UNKNOWN_ERROR';
    22|
    23|interface Props {
    24|  moduleName: string;
    25|  children: ReactNode;
    26|  /** Optional fallback render when no error */
    27|  fallback?: ReactNode;
    28|}
    29|
    30|interface State {
    31|  hasError: boolean;
    32|  error: Error | null;
    33|  category: ErrorCategory;
    34|  traceId: string | null;
    35|}
    36|
    37|function classifyError(error: Error): ErrorCategory {
    38|  const msg = (error.message || '').toLowerCase();
    39|  if (msg.includes('maximum update depth') || msg.includes('render')) return 'RENDER_ERROR';
    40|  if (msg.includes('auth') || msg.includes('session') || msg.includes('token')) return 'AUTH_ERROR';
    41|  if (msg.includes('network') || msg.includes('fetch') || msg.includes('timeout')) return 'NETWORK_ERROR';
    42|  if (msg.includes('supabase url') || msg.includes('config')) return 'CONFIG_ERROR';
    43|  if (msg.includes('data') || msg.includes('parse') || msg.includes('json')) return 'DATA_ERROR';
    44|  return 'UNKNOWN_ERROR';
    45|}
    46|
    47|function generateTraceId(): string {
    48|  return 'IVX-' + Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 8);
    49|}
    50|
    51|const CATEGORY_MESSAGES: Record<ErrorCategory, string> = {
    52|  AUTH_ERROR: 'Authentication required. Please sign in and try again.',
    53|  NETWORK_ERROR: 'Network connection issue. Check your internet and retry.',
    54|  DATA_ERROR: 'Could not load data from the server.',
    55|  RENDER_ERROR: 'This section encountered a rendering error.',
    56|  CONFIG_ERROR: 'Configuration issue detected.',
    57|  UNKNOWN_ERROR: 'An unexpected error occurred.',
    58|};
    59|
    60|export class ModuleErrorBoundary extends Component<Props, State> {
    61|  state: State = { hasError: false, error: null, category: 'UNKNOWN_ERROR', traceId: null };
    62|
    63|  static getDerivedStateFromError(error: Error): Partial<State> {
    64|    return {
    65|      hasError: true,
    66|      error,
    67|      category: classifyError(error),
    68|      traceId: generateTraceId(),
    69|    };
    70|  }
    71|
    72|  componentDidCatch(error: Error) {
    73|    console.warn(`[ModuleErrorBoundary:${this.props.moduleName}]`, this.state.traceId, this.state.category, error.message);
    74|  }
    75|
    76|  handleRetry = () => {
    77|    this.setState({ hasError: false, error: null, category: 'UNKNOWN_ERROR', traceId: null });
    78|  };
    79|
    80|  render() {
    81|    if (this.state.hasError) {
    82|      return (
    83|        <View style={styles.container}>
    84|          <View style={styles.card}>
    85|            <View style={styles.iconWrap}>
    86|              <AlertCircle size={28} color="#FF6B6B" />
    87|            </View>
    88|            <Text style={styles.moduleName}>{this.props.moduleName}</Text>
    89|            <Text style={styles.message}>{CATEGORY_MESSAGES[this.state.category]}</Text>
    90|            {this.state.traceId && (
    91|              <Text style={styles.traceId}>Trace: {this.state.traceId}</Text>
    92|            )}
    93|            <TouchableOpacity style={styles.retryButton} onPress={this.handleRetry} activeOpacity={0.8}>
    94|              <RefreshCw size={16} color="#000" />
    95|              <Text style={styles.retryText}>Retry {this.props.moduleName}</Text>
    96|            </TouchableOpacity>
    97|          </View>
    98|        </View>
    99|      );
   100|    }
   101|    return this.props.children;
   102|  }
   103|}
