{"command": "cd /home/user/rork-app && python3 - << 'PYEOF'
import json, urllib.request

token = json.loads(open('/tmp/owner_at.json').read())['accessToken']

# Re-run landing deploy now that backend is on 95fc5938 (latest commit with v1.4.34 index.html)
url = 'https://api.ivxholding.com/api/ivx/landing-deploy'
headers = {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}
payload = json.dumps({'confirm': 'DEPLOY_IVX_LANDING_FULL'}).encode('utf-8')
req = urllib.request.Request(url, data=payload, headers=headers, method='POST')
try:
    with urllib.request.urlopen(req, timeout=120) as resp:
        data = json.loads(resp.read().decode('utf-8'))
        for u in data.get('uploads', []):
            if u['key'] == 'index.html':
                print(f"index.html uploaded: {u['bytes']} bytes, ok={u['ok']}")
        print(f"ok: {data.get('ok')}")
except urllib.error.HTTPError as e:
    print(f'HTTP {e.code}: {e.read().decode("utf-8")[:300]}')
PYEOF"}
